CREATE OR REPLACE FUNCTION public.fn_get_weekly_planning_draft_items(p_tenant_id uuid, p_request_id uuid)  RETURNS TABLE(id uuid, request_id uuid, tenant_id uuid, scheduled_date date, day_of_week character varying, time_of_day character varying, experience_id uuid, experience_title character varying, learning_goal text, group_format character varying, estimated_duration_minutes integer, required_materials text, rationale text, validation_status character varying, validation_notes text, resulting_schedule_id uuid, created_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          id, request_id, tenant_id, scheduled_date, day_of_week, time_of_day,         experience_id, experience_title, learning_goal, group_format,         estimated_duration_minutes, required_materials, rationale,         validation_status, validation_notes, resulting_schedule_id, created_at     FROM weekly_planning_draft_items     WHERE tenant_id = p_tenant_id AND request_id = p_request_id     ORDER BY scheduled_date ASC, time_of_day ASC; $function$ ;
